# Stable slugs for the six directions shipped in seed/content.json. Matching uses distinctive
# words of the original titles so renamed or extra directions still get a unique fallback.
DIRECTION_SLUGS = [
    ("病毒性感染中毒症", "viral-sepsis", "病毒性感染中毒症", (1, 1, 1, 1)),
    ("精准感染诊断", "pathogen-diagnosis", "病原与精准诊断", (1, 0, 1, 1)),
    ("抗病毒药物", "antiviral-evaluation", "抗病毒药物评价", (0, 0, 1, 1)),
    ("真实世界", "real-world-evidence", "真实世界研究", (1, 1, 1, 0)),
    ("微生物组", "microbiome", "呼吸道微生物组", (1, 1, 1, 1)),
    ("临床转化", "translation", "临床转化", (1, 1, 1, 1)),
]


def backfill_directions(apps, schema_editor):
    Direction = apps.get_model("catalog", "ResearchDirection")
    used = set()
    for direction in Direction.objects.order_by("position", "pk"):
        slug = None
        for marker, candidate, short, layers in DIRECTION_SLUGS:
            if marker in direction.title and candidate not in used:
                slug = candidate
                if not direction.short_title:
                    direction.short_title = short
                if not any((direction.covers_pathogen, direction.covers_host, direction.covers_clinical, direction.covers_intervention)):
                    (direction.covers_pathogen, direction.covers_host,
                     direction.covers_clinical, direction.covers_intervention) = map(bool, layers)
                break
        if slug is None:
            slug = slugify(direction.title)[:60] or f"direction-{direction.pk}"
        base, number = slug, 2
        while slug in used:
            slug, number = f"{base}-{number}", number + 1
        used.add(slug)
        # update() keeps updated_at/version untouched: this is a schema backfill, not an edit.
        Direction.objects.filter(pk=direction.pk).update(
            slug=slug, short_title=direction.short_title, covers_pathogen=direction.covers_pathogen,
            covers_host=direction.covers_host, covers_clinical=direction.covers_clinical,
            covers_intervention=direction.covers_intervention)


def backfill_publications(apps, schema_editor):
    Publication = apps.get_model("catalog", "Publication")
    used = set(Publication.objects.exclude(slug=None).values_list("slug", flat=True))
    for item in Publication.objects.filter(slug=None).order_by("pk"):
        base = slugify(f"{item.year} {' '.join(item.title.split()[:6])}")[:60].strip("-")
        if not base or base == str(item.year):
            base = f"{item.year}-item-{item.pk}"
        slug, number = base, 2
        while slug in used:
            slug, number = f"{base}-{number}", number + 1
        used.add(slug)
        Publication.objects.filter(pk=item.pk).update(slug=slug)


def update_pages(apps, schema_editor):
    Page = apps.get_model("catalog", "Page")
    if not Page.objects.exists():
        return  # fresh database: seed_site creates every page.
    Page.objects.get_or_create(slug="projects", defaults={
        "title": "科研课题", "english": "Research Projects", "intro": "课题组承担的科研课题档案。"})
    # Only replace texts that still carry the original defaults; edited texts are kept.
    Page.objects.filter(slug="contact", title="联系我们").update(title="联系与加入")
    Page.objects.filter(slug="contact", english="Contact").update(english="Contact & Join")
    Page.objects.filter(slug="publications", intro="科研项目、研究论文与其他科研成果。").update(
        intro="代表性研究论文与其他科研成果，目录持续整理。")


